css:
.sl-learning-paths.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-learning-paths .sl-step-card, .sl-learning-paths .sl-step-circle { background-color: var(--smartlearn-bg); }
.sl-learning-paths .sl-text-primary { color: var(--smartlearn-primary); }
.sl-learning-paths .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-learning-paths .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-learning-paths .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-learning-paths .sl-border { border-color: var(--smartlearn-card-border); }
.sl-learning-paths .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-learning-paths h2, .sl-learning-paths h3, .sl-learning-paths h4 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-learning-paths .sl-tracking-wide { letter-spacing: 0.1em; }
.sl-learning-paths .sl-badge-subtle {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
    color: var(--smartlearn-primary);
    border: 1px solid var(--smartlearn-card-border);
    border: 1px solid color-mix(in oklab, var(--smartlearn-primary) 28%, var(--smartlearn-card-border));
}
.sl-learning-paths .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid var(--smartlearn-btn-bg);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-learning-paths .sl-btn-primary:hover,
.sl-learning-paths .sl-btn-primary:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-learning-paths .sl-btn-outline {
    background-color: transparent;
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-learning-paths .sl-btn-outline:hover,
.sl-learning-paths .sl-btn-outline:focus-visible {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-learning-paths .sl-timeline-line {
    inset-inline-start: 24px;
    top: 24px;
    bottom: 24px;
    width: 1px;
    border-inline-start: 1px solid var(--smartlearn-card-border);
}
.sl-learning-paths .sl-step-circle {
    width: 48px;
    height: 48px;
    border: 4px solid var(--smartlearn-card-bg);
}
.sl-learning-paths .sl-step-active {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-learning-paths .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-learning-paths .sl-btn-primary, .sl-learning-paths .sl-btn-outline { transition: none; }
}
@media (min-width: 992px) {
    .sl-learning-paths { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}
